import{_ as e,o as r,c as t,a2 as l}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"Ceph Developer Monthly 2020-11-04","description":"","frontmatter":{"title":"Ceph Developer Monthly 2020-11-04","date":"2020-11-04T00:00:00.000Z","updated":"2020-11-18T00:00:00.000Z","tags":["Ceph","分布式存储","Manager 可扩展性","Replicated Writeback Cache (RWD)","Dashboard 设计改进"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/Ceph_Developer_Monthly_2020-11-04.md","filePath":"posts/2020/Ceph_Developer_Monthly_2020-11-04.md","lastUpdated":1780460162000}'),o={name:"posts/2020/Ceph_Developer_Monthly_2020-11-04.md"};function i(n,a,h,s,d,c){return r(),t("div",null,[...a[0]||(a[0]=[l('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议主题-ceph-开发者月度会议-2020年11月" tabindex="-1">会议主题：Ceph 开发者月度会议 - 2020年11月 <a class="header-anchor" href="#会议主题-ceph-开发者月度会议-2020年11月" aria-label="Permalink to &quot;会议主题：Ceph 开发者月度会议 - 2020年11月&quot;">​</a></h4><h4 id="参会人员-ceph-开发团队成员" tabindex="-1">参会人员：Ceph 开发团队成员 <a class="header-anchor" href="#参会人员-ceph-开发团队成员" aria-label="Permalink to &quot;参会人员：Ceph 开发团队成员&quot;">​</a></h4><h4 id="会议议程" tabindex="-1">会议议程： <a class="header-anchor" href="#会议议程" aria-label="Permalink to &quot;会议议程：&quot;">​</a></h4><ol><li><strong>Manager 可扩展性讨论</strong></li><li><strong>Replicated Writeback Cache (RWD) 介绍</strong></li><li><strong>Dashboard 设计协作改进</strong></li></ol><h4 id="关键细节" tabindex="-1">关键细节： <a class="header-anchor" href="#关键细节" aria-label="Permalink to &quot;关键细节：&quot;">​</a></h4><h5 id="_1-manager-可扩展性讨论" tabindex="-1">1. Manager 可扩展性讨论 <a class="header-anchor" href="#_1-manager-可扩展性讨论" aria-label="Permalink to &quot;1. Manager 可扩展性讨论&quot;">​</a></h5><ul><li><strong>问题识别</strong>：讨论了 Manager 在高负载下的性能问题，包括 CPU 使用率高和处理延迟增加。</li><li><strong>性能瓶颈</strong>：集中在 Manager 模块的某些部分，如 Finisher 队列处理大量完成项时导致延迟。</li><li><strong>短期解决方案</strong>：减少 OSD 报告频率，优化数据处理效率，引入监控和调试工具。</li><li><strong>长期解决方案</strong>：分解 Manager 模块，引入更多监控和调试工具。</li><li><strong>后续行动</strong>：收集性能数据，分析并优化代码。</li></ul><h5 id="_2-replicated-writeback-cache-rwd-介绍" tabindex="-1">2. Replicated Writeback Cache (RWD) 介绍 <a class="header-anchor" href="#_2-replicated-writeback-cache-rwd-介绍" aria-label="Permalink to &quot;2. Replicated Writeback Cache (RWD) 介绍&quot;">​</a></h5><ul><li><strong>项目背景</strong>：RWD 是一个基于持久内存的缓存系统，旨在提高数据处理的效率。</li><li><strong>当前进展</strong>：已完成第一阶段，即单副本缓存实现；第二阶段将实现跨设备的数据复制。</li><li><strong>技术挑战</strong>：管理多个副本的状态和数据一致性，处理节点故障时的数据恢复和重新分配。</li><li><strong>后续行动</strong>：测试和验证 RWD 的性能和可靠性。</li></ul><h5 id="_3-dashboard-设计协作改进" tabindex="-1">3. Dashboard 设计协作改进 <a class="header-anchor" href="#_3-dashboard-设计协作改进" aria-label="Permalink to &quot;3. Dashboard 设计协作改进&quot;">​</a></h5><ul><li><strong>问题识别</strong>：设计团队和开发团队之间的协作需要改进。</li><li><strong>解决方案</strong>：通过设计拉取请求（Design Pull Requests）的方式，将设计文档提交到开发仓库中。</li><li><strong>后续行动</strong>：继续使用设计拉取请求，优化流程。</li></ul><h4 id="决定事项" tabindex="-1">决定事项： <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项：&quot;">​</a></h4><ul><li>确认了 Manager 模块的性能优化方向和短期行动计划。</li><li>确定了 RWD 项目的下一步测试和简化实现的策略。</li><li>同意继续使用设计拉取请求的方式，改进 Dashboard 的设计协作。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li>收集和分析 Manager 的性能数据，优化代码和配置。</li><li>测试 RWD 的性能，简化初始实现。</li><li>继续使用设计拉取请求，优化 Dashboard 的设计协作流程。</li></ul><h4 id="会议结束" tabindex="-1">会议结束： <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束：&quot;">​</a></h4><p>感谢所有参与者的贡献，期待在下一次会议中继续讨论和推进项目的进展。</p>',18)])])}const u=e(o,[["render",i]]);export{g as __pageData,u as default};
